package org.eclipse.rdf4j.queryrender;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

import java.io.ByteArrayOutputStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Map;

import javax.tools.JavaCompiler;
import javax.tools.ToolProvider;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.queryrender.sparql.PrefixIndex;
import org.eclipse.rdf4j.queryrender.sparql.util.TermRenderer;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class BlankNodeReferenceRenderingTest {
	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void fixedOperandsRenderAsReferences() {
		assertEquals("<_:fixed>", RenderUtils.toSPARQL(VF.createBNode("fixed")));
		assertEquals("<_:fixed>", TermRenderer.convertValueToString(VF.createBNode("fixed"),
				new PrefixIndex(Map.of()), false));
	}

	@Test
	void referenceIdsEscapeDelimitersAndBackslash() {
		assertEquals("<_:a\\u0020b\\u003E\\u005C>", RenderUtils.toSPARQL(VF.createBNode("a b>\\")));
	}

	@Test
	void referencesRenderRecursivelyInTripleTerms() {
		assertEquals("<<(<_:s> <urn:p> <_:o>)>>", RenderUtils.toSPARQL(
				VF.createTripleTerm(VF.createBNode("s"), VF.createIRI("urn:p"), VF.createBNode("o"))));
	}

	@Test
	void legacyNullBuilderOverloadRemainsSourceCompatible(@TempDir Path tempDir) throws Exception {
		JavaCompiler compiler = ToolProvider.getSystemJavaCompiler();
		assertNotNull(compiler, "the test runtime must include a Java compiler");
		Path source = tempDir.resolve("LegacyRenderUtilsOverload.java");
		Files.writeString(source, "package org.eclipse.rdf4j.queryrender;\n"
				+ "import org.eclipse.rdf4j.model.impl.SimpleValueFactory;\n"
				+ "class LegacyRenderUtilsOverload { StringBuilder render() { return RenderUtils.toSPARQL("
				+ "SimpleValueFactory.getInstance().createIRI(\"urn:x\"), null); } }\n");
		String classPath = System.getProperty("surefire.test.class.path", System.getProperty("java.class.path"));
		ByteArrayOutputStream compilerOutput = new ByteArrayOutputStream();
		int result = compiler.run(null, null, compilerOutput, "-classpath", classPath, "-d", tempDir.toString(),
				source.toString());
		assertEquals(0, result,
				"legacy `toSPARQL(value, null)` source must still compile: "
						+ compilerOutput.toString(java.nio.charset.StandardCharsets.UTF_8));
	}
}
